        """Complete choices that start with the incomplete value.

        :param ctx: Invocation context for this command.
        :param param: The parameter that is requesting completion.
        :param incomplete: Value being completed. May be empty.

        .. versionadded:: 8.0
        """
        from click.shell_completion import CompletionItem

        normalized_mapping = self._normalized_mapping(ctx=ctx)
        # A subclass may normalize values into the forms that should be
        # displayed and passed on the command line. The default behavior only
        # normalizes for matching and keeps showing ``str()`` values.
        subclassed_normalization = type(self).normalize_choice is not Choice.normalize_choice

        def completion_value(choice: ParamTypeValue, normalized: str) -> str:
            if subclassed_normalization:
                return normalized
            return str(choice)

        if self.case_sensitive:
            matched = (
                completion_value(choice, normalized)
                for choice, normalized in normalized_mapping.items()
                if normalized.startswith(incomplete)
            )
        else:
            incomplete = incomplete.lower()
            matched = (
                completion_value(choice, normalized)
                for choice, normalized in normalized_mapping.items()
                if normalized.lower().startswith(incomplete)
            )

        return [CompletionItem(c) for c in matched]


